mapper.select:
SELECT r.currency, r.base_rate, r.final_rate, r.price_date AS rate_date FROM fx_daily_rate r JOIN ( SELECT currency, MAX(price_date) AS price_date FROM fx_daily_rate WHERE price_date <= #{asOf} AND currency IN
#{currency}
GROUP BY currency ) latest ON latest.currency = r.currency AND latest.price_date = r.price_date ORDER BY r.currency
